const modulePath = (key: string) => `/admin/${key.replaceAll('_', '-')}`;
const dateLabel = (value: unknown, lang: string) => { const date = new Date(String(value)); return Number.isNaN(date.getTime()) ? '—' : new Intl.DateTimeFormat(lang === 'ar' ? 'ar' : 'en', { month: 'short', day: 'numeric', year: 'numeric' }).format(date); };
