function Loading() { const { t } = useLanguage(); return <div className="admin-loading" role="status"><Loader2 className="admin-spin" size={24} />{t('Loading your workspace…', 'جارٍ تحميل مساحة العمل…')}</div>; }
function Alert({ children, success = false }: { children: ReactNode; success?: boolean }) { return <div className={`admin-alert ${success ? 'is-success' : ''}`} role={success ? 'status' : 'alert'}>{success && <CheckCircle2 size={18} />}{children}</div>; }

function Modal({ title, children, onClose, narrow = false }: { title: string; children: ReactNode; onClose: () => void; narrow?: boolean }) {
  const dialogRef = useRef<HTMLDivElement>(null);
  const closeRef = useRef(onClose);
  closeRef.current = onClose;
  const { t } = useLanguage();
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    const overflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    const dialog = dialogRef.current;
    dialog?.querySelector<HTMLElement>('button, input, textarea, select, [tabindex="0"]')?.focus();
    const handler = (event: KeyboardEvent) => {
      if (event.key === 'Escape') closeRef.current();
      if (event.key === 'Tab' && dialog) {
        const items = Array.from(dialog.querySelectorAll<HTMLElement>('button:not([disabled]), a[href], input:not([disabled]), textarea:not([disabled]), select:not([disabled]), [tabindex="0"]'));
        const first = items[0], last = items[items.length - 1];
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
      }
    };
    document.addEventListener('keydown', handler);
    return () => { document.removeEventListener('keydown', handler); document.body.style.overflow = overflow; previous?.focus(); };
  }, []);
  return <div className="admin-modal-backdrop" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}><div ref={dialogRef} className={`admin-modal ${narrow ? 'admin-modal-narrow' : ''}`} role="dialog" aria-modal="true" aria-labelledby="admin-modal-title"><div className="admin-modal-header"><h2 id="admin-modal-title">{title}</h2><button type="button" className="admin-icon-button" onClick={onClose} aria-label={t('Close dialog', 'إغلاق النافذة')}><X size={20} /></button></div>{children}</div></div>;
}

function Login() {
  const auth = useAuth();
  const { t, lang, toggleLanguage } = useLanguage();
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  if (auth.loading) return <Loading />;
  if (auth.isAdmin) return <Navigate to="/admin" replace />;
  async function submit(event: FormEvent) {
    event.preventDefault(); setBusy(true); setError('');
    try { await auth.login(email, password); navigate('/admin'); }
    catch (err) { setError(errorText(err)); } finally { setBusy(false); }
  }
  function demo() { try { auth.enterDemo(); navigate('/admin'); } catch (err) { setError(errorText(err)); } }
  return <div className="admin-root admin-login" dir={lang === 'ar' ? 'rtl' : 'ltr'}><div className="admin-login-story"><Brand light /><div><span className="admin-eyebrow">APEX MOTORS / CONTENT STUDIO</span><h1>{t('Excellence starts\nbehind the scenes.', 'التميّز يبدأ\nمن خلف الكواليس.')}</h1><p>{t('One workspace. Every detail of your brand.', 'مساحة واحدة لكل تفاصيل علامتك التجارية.')}</p></div><span className="admin-login-copyright">© {new Date().getFullYear()} Apex Motors</span></div><div className="admin-login-main"><button className="admin-language" onClick={toggleLanguage}><Globe2 size={17} />{lang === 'en' ? 'العربية' : 'English'}</button><div className="admin-login-card"><div className="admin-login-shield"><ShieldCheck size={26} /></div><span className="admin-eyebrow">{t('ADMINISTRATOR ACCESS', 'دخول المسؤول')}</span><h2>{t('Welcome back.', 'مرحباً بعودتك.')}</h2><p>{t('Sign in to manage your Apex Motors website.', 'سجّل الدخول لإدارة موقع أبيكس موتورز.')}</p>{error && <Alert>{error}</Alert>}<form onSubmit={submit}><label className="admin-field">{t('Email address', 'البريد الإلكتروني')}<input required type="email" autoComplete="username" value={email} onChange={e => setEmail(e.target.value)} placeholder="you@apexmotors.com" dir="ltr" /></label><label className="admin-field">{t('Password', 'كلمة المرور')}<input required type="password" autoComplete="current-password" minLength={6} value={password} onChange={e => setPassword(e.target.value)} /></label><button className="admin-button admin-button-primary admin-button-full" disabled={busy}>{busy ? <Loader2 size={17} className="admin-spin" /> : <ArrowRight size={17} />}{t('Sign in securely', 'تسجيل الدخول بأمان')}</button></form>{demoEnabled && <div className="admin-demo-entry"><p>{t('Explore the local demonstration workspace. Changes are saved in this browser.', 'استكشف مساحة العرض المحلية. تُحفظ التغييرات في هذا المتصفح.')}</p><button className="admin-button admin-button-full" onClick={demo}>{t('Open demo workspace', 'فتح مساحة العرض التجريبي')}<ArrowUpRight size={17} /></button></div>}<Link to="/" className="admin-back-link"><ArrowLeft size={15} />{t('Back to the website', 'العودة إلى الموقع')}</Link></div></div></div>;
}

