function EmptyState({ icon: Icon, title, description }: { icon: LucideIcon; title: string; description: string }) { return <div className="admin-empty"><span><Icon size={28} /></span><h3>{title}</h3><p>{description}</p></div>; }
function Badge({ status }: { status: string }) { const { t } = useLanguage(); const names: Record<string, string> = { published: 'منشور', draft: 'مسودة', archived: 'مؤرشف', active: 'نشط', inactive: 'غير نشط', read: 'مقروء', unread: 'غير مقروء' }; return <span className={`admin-badge admin-badge-${status}`}><i />{t(status.charAt(0).toUpperCase() + status.slice(1), names[status] || status)}</span>; }

function ModulePage({ module }: { module: AdminModule }) {
  const { data, save, remove } = useCms(); const { t, lang } = useLanguage();
  const navigate = useNavigate(); const { '*': selectedId } = useParams();
  const [query, setQuery] = useState(''), [filter, setFilter] = useState('all'), [sort, setSort] = useState('order'), [page, setPage] = useState(1);
  const [deleting, setDeleting] = useState<ContentRecord | null>(null), [busy, setBusy] = useState(false), [error, setError] = useState(''), [notice, setNotice] = useState(''), [upload, setUpload] = useState(false);
  const records = data[module.key] || [];
  const isMessages = module.key === 'contact_messages', isSubscribers = module.key === 'newsletter_subscribers', isMedia = module.key === 'media';
  const isPrivate = isMessages || isSubscribers;
  const selected = selectedId && selectedId !== 'new' ? records.find(record => record.id === selectedId) : null;
  const filtered = useMemo(() => records.filter(record => {
    const matchesQuery = [record.title_en, record.title_ar, record.slug, field(record, 'email'), field(record, 'name'), field(record, 'subject'), field(record, 'message')].join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase());
    const state = isMessages ? (record.is_read ? 'read' : 'unread') : record.status;
    return matchesQuery && (filter === 'all' || state === filter);
  }).sort((a, b) => sort === 'title' ? contentTitle(a, lang).localeCompare(contentTitle(b, lang)) : sort === 'oldest' ? a.created_at.localeCompare(b.created_at) : sort === 'newest' ? b.created_at.localeCompare(a.created_at) : Number(a.sort_order || 0) - Number(b.sort_order || 0)), [records, query, filter, sort, isMessages, lang]);
  const pageCount = Math.max(1, Math.ceil(filtered.length / 8)), currentPage = Math.min(page, pageCount), visible = filtered.slice((currentPage - 1) * 8, currentPage * 8);
  useEffect(() => setPage(1), [query, filter]);
  async function changeRecord(record: ContentRecord, patch: Partial<ContentRecord>) { setError(''); try { await save(module.key, { ...record, ...patch }); setNotice(t('Changes saved.', 'تم حفظ التغييرات.')); } catch (err) { setError(errorText(err)); } }
  async function deleteRecord() { if (!deleting) return; setBusy(true); setError(''); try { await remove(module.key, deleting.id); setDeleting(null); setNotice(t('Record deleted.', 'تم حذف السجل.')); } catch (err) { setError(errorText(err)); } finally { setBusy(false); } }
  function closeEditor() { navigate(modulePath(module.key)); }
  return <><div className="admin-page-heading"><div><span className="admin-eyebrow">{t(module.group === 'audience' ? 'YOUR COMMUNITY' : 'CONTENT STUDIO', module.group === 'audience' ? 'مجتمعك' : 'استوديو المحتوى')}</span><h1>{t(module.en, module.ar)}<span className="admin-count-pill">{records.length}</span></h1><p>{t(module.description, module.descriptionAr)}</p></div>{!isPrivate && <button className="admin-button admin-button-primary" onClick={() => isMedia ? setUpload(true) : navigate(`${modulePath(module.key)}/new`)}>{isMedia ? <UploadCloud size={17} /> : <Plus size={17} />}{isMedia ? t('Upload media', 'رفع وسائط') : t('Add new', 'إضافة جديد')}</button>}</div>{error && <Alert>{error}</Alert>}{notice && <Alert success>{notice}<button className="admin-icon-button" onClick={() => setNotice('')} aria-label={t('Dismiss', 'إغلاق')}><X size={15} /></button></Alert>}<section className="admin-panel"><div className="admin-table-toolbar"><div className="admin-search"><Search size={18} /><input aria-label={t('Search records', 'البحث في السجلات')} placeholder={t(`Search ${module.en.toLowerCase()}…`, `البحث في ${module.ar}…`)} value={query} onChange={event => setQuery(event.target.value)} />{query && <button className="admin-icon-button" onClick={() => setQuery('')} aria-label={t('Clear search', 'مسح البحث')}><X size={15} /></button>}</div><label className="admin-filter"><SlidersHorizontal size={15} /><span className="admin-sr-only">{t('Filter by status', 'تصفية حسب الحالة')}</span><select value={filter} onChange={event => setFilter(event.target.value)}><option value="all">{t('All statuses', 'جميع الحالات')}</option>{(isMessages ? ['unread', 'read'] : isSubscribers ? ['active', 'inactive'] : ['published', 'draft', 'archived']).map(status => <option key={status} value={status}>{t(status.charAt(0).toUpperCase() + status.slice(1), ({ published: 'منشور', draft: 'مسودة', archived: 'مؤرشف', active: 'نشط', inactive: 'غير نشط', unread: 'غير مقروء', read: 'مقروء' } as Record<string, string>)[status])}</option>)}</select></label><label className="admin-filter"><ArrowDown size={15} /><span className="admin-sr-only">{t('Sort records', 'ترتيب السجلات')}</span><select value={sort} onChange={event => setSort(event.target.value)}><option value="order">{t('Display order', 'ترتيب العرض')}</option><option value="newest">{t('Newest first', 'الأحدث أولاً')}</option><option value="oldest">{t('Oldest first', 'الأقدم أولاً')}</option><option value="title">{t('Title A–Z', 'العنوان أبجدياً')}</option></select></label></div>{filtered.length ? isMedia ? <div className="admin-media-grid">{visible.map(record => <article key={record.id} className="admin-media-card"><button className="admin-media-preview" onClick={() => navigate(`${modulePath(module.key)}/${record.id}`)}><img src={safeImageUrl(record.image || field(record, 'url'))} alt={localized(record, 'alt_text', lang) || contentTitle(record, lang)} /></button><div><strong>{contentTitle(record, lang)}</strong><small>{dateLabel(record.created_at, lang)}</small><div className="admin-media-card-actions"><button className="admin-icon-button" onClick={() => navigate(`${modulePath(module.key)}/${record.id}`)} aria-label={t('Edit image', 'تعديل الصورة')}><Pencil size={16} /></button><button className="admin-icon-button admin-danger-text" onClick={() => setDeleting(record)} aria-label={t('Delete image', 'حذف الصورة')}><Trash2 size={16} /></button></div></div></article>)}</div> : <div className="admin-table-scroll"><table className="admin-table"><thead><tr><th>{isMessages ? t('From / subject', 'المرسل / الموضوع') : isSubscribers ? t('Subscriber', 'المشترك') : t('Title', 'العنوان')}</th><th>{t('Status', 'الحالة')}</th>{!isPrivate && <th>{t('Languages', 'اللغات')}</th>}<th>{t('Date', 'التاريخ')}</th><th className="admin-actions-heading">{t('Actions', 'الإجراءات')}</th></tr></thead><tbody>{visible.map(record => <tr key={record.id}><td><button className="admin-table-title" onClick={() => navigate(`${modulePath(module.key)}/${record.id}`)}>{record.image && !isPrivate ? <img src={safeImageUrl(record.image)} alt="" /> : <span className="admin-record-icon">{isMessages ? <Mail size={18} /> : isSubscribers ? <Users size={18} /> : <FileText size={18} />}</span>}<span><strong>{isMessages ? field(record, 'name') || field(record, 'email') : contentTitle(record, lang)}</strong><small>{isMessages ? field(record, 'subject') : isSubscribers ? field(record, 'email') : record.slug}</small></span></button></td><td><Badge status={isMessages ? record.is_read ? 'read' : 'unread' : record.status} />{!isPrivate && !record.active && <small className="admin-inactive-label">{t('Hidden', 'مخفي')}</small>}</td>{!isPrivate && <td><span className={`admin-language-chip ${record.title_en ? 'complete' : ''}`}>EN</span><span className={`admin-language-chip ${record.title_ar ? 'complete' : ''}`}>AR</span></td>}<td className="admin-table-date">{dateLabel(record.created_at, lang)}</td><td><div className="admin-row-actions"><button className="admin-icon-button" title={isMessages ? t('Read message', 'قراءة الرسالة') : t('Edit record', 'تعديل السجل')} aria-label={isMessages ? t('Read message', 'قراءة الرسالة') : t('Edit record', 'تعديل السجل')} onClick={() => navigate(`${modulePath(module.key)}/${record.id}`)}>{isMessages ? <Eye size={17} /> : <Pencil size={16} />}</button><button className="admin-icon-button" title={isMessages ? t('Toggle read status', 'تغيير حالة القراءة') : isSubscribers ? t('Toggle active status', 'تغيير حالة النشاط') : t('Publish / unpublish', 'نشر / إلغاء النشر')} aria-label={isMessages ? t('Toggle read status', 'تغيير حالة القراءة') : isSubscribers ? t('Toggle active status', 'تغيير حالة النشاط') : t('Publish / unpublish', 'نشر / إلغاء النشر')} onClick={() => void changeRecord(record, isMessages ? { is_read: !record.is_read } : isSubscribers ? { status: record.status === 'active' ? 'inactive' : 'active', active: record.status !== 'active' } : { status: record.status === 'published' ? 'draft' : 'published' })}>{isMessages ? <Check size={17} /> : <CheckCircle2 size={17} />}</button><button className="admin-icon-button admin-danger-text" onClick={() => setDeleting(record)} title={t('Delete record', 'حذف السجل')} aria-label={t('Delete record', 'حذف السجل')}><Trash2 size={16} /></button></div></td></tr>)}</tbody></table></div> : <EmptyState icon={query ? Search : icons[module.icon]} title={query || filter !== 'all' ? t('No matching results', 'لا توجد نتائج مطابقة') : t('A fresh start', 'بداية جديدة')} description={query || filter !== 'all' ? t('Try a different search or clear your filters.', 'جرّب بحثاً مختلفاً أو امسح عوامل التصفية.') : t('Your content will appear here when added.', 'سيظهر المحتوى هنا بعد إضافته.')} />}<div className="admin-pagination"><span>{filtered.length ? `${(currentPage - 1) * 8 + 1}–${Math.min(currentPage * 8, filtered.length)}` : '0'} {t('of', 'من')} {filtered.length} {t('records', 'سجلات')}</span><div><button className="admin-icon-button" disabled={currentPage === 1} onClick={() => setPage(currentPage - 1)} aria-label={t('Previous page', 'الصفحة السابقة')}><ChevronLeft size={18} /></button><span>{currentPage} / {pageCount}</span><button className="admin-icon-button" disabled={currentPage === pageCount} onClick={() => setPage(currentPage + 1)} aria-label={t('Next page', 'الصفحة التالية')}><ChevronRight size={18} /></button></div></div></section>{deleting && <Modal title={t('Delete this record?', 'حذف هذا السجل؟')} onClose={() => { if (!busy) setDeleting(null); }} narrow><div className="admin-modal-body"><div className="admin-delete-icon"><Trash2 size={26} /></div><p>{t('This permanently removes', 'سيؤدي هذا إلى حذف')} <strong>{contentTitle(deleting, lang)}</strong>. {t('This action cannot be undone.', 'لا يمكن التراجع عن هذا الإجراء.')}</p>{module.key === 'albums' && <p className="admin-help">{t('Images in this album are also removed from the gallery.', 'ستُحذف صور هذا الألبوم أيضاً من المعرض.')}</p>}<div className="admin-modal-actions"><button className="admin-button" disabled={busy} onClick={() => setDeleting(null)}>{t('Cancel', 'إلغاء')}</button><button className="admin-button admin-button-primary" disabled={busy} onClick={() => void deleteRecord()}>{busy && <Loader2 className="admin-spin" size={15} />}{t('Delete record', 'حذف السجل')}</button></div></div></Modal>}{upload && <UploadModal onClose={() => setUpload(false)} onSuccess={() => { setUpload(false); setNotice(t('Media uploaded successfully.', 'تم رفع الوسائط بنجاح.')); }} />}{selectedId === 'new' && !isPrivate && !isMedia && <ContentEditor module={module} record={emptyRecord()} isNew onClose={closeEditor} onSaved={() => { closeEditor(); setNotice(t('Content created.', 'تم إنشاء المحتوى.')); }} />}{selected && (isMessages ? <MessageViewer record={selected} onClose={closeEditor} /> : isSubscribers ? <SubscriberEditor record={selected} onClose={closeEditor} /> : <ContentEditor module={module} record={selected} onClose={closeEditor} onSaved={() => { closeEditor(); setNotice(t('Changes saved.', 'تم حفظ التغييرات.')); }} />)}{selectedId && selectedId !== 'new' && !selected && <Modal title={t('Record not found', 'السجل غير موجود')} onClose={closeEditor} narrow><div className="admin-modal-body"><p>{t('This record may have been removed. Return to the list to continue.', 'ربما تم حذف هذا السجل. عد إلى القائمة للمتابعة.')}</p><button className="admin-button" onClick={closeEditor}>{t('Back to records', 'العودة إلى السجلات')}</button></div></Modal>}</>;
}

function DynamicField({ definition, value, onChange }: { definition: FieldDefinition; value: unknown; onChange: (value: unknown) => void }) {
  const { t } = useLanguage(); const { key, kind = 'text' } = definition;
  const stringValue = kind === 'lines' ? Array.isArray(value) ? value.join('\n') : String(value || '') : kind === 'json' ? typeof value === 'string' ? value : JSON.stringify(value || [], null, 2) : String(value ?? '');
  const props = { id: `admin-field-${key}`, required: definition.required, dir: key.endsWith('_ar') ? 'rtl' as const : key.endsWith('_en') || /url|link|href|email|phone|image/.test(key) ? 'ltr' as const : undefined };
  return <label className={`admin-field ${definition.wide ? 'admin-field-wide' : ''}`} htmlFor={props.id}><span>{t(definition.en, definition.ar)}{definition.required && <b> *</b>}</span>{kind === 'select' ? <select {...props} value={stringValue} onChange={event => onChange(event.target.value)}><option value="">{t('Select…', 'اختر…')}</option>{definition.options?.map(option => <option key={option.value} value={option.value}>{option.label}</option>)}</select> : kind === 'textarea' || kind === 'lines' || kind === 'json' ? <textarea {...props} rows={kind === 'json' ? 6 : 4} value={stringValue} onChange={event => onChange(kind === 'lines' ? event.target.value.split('\n') : event.target.value)} /> : <input {...props} type={kind === 'number' ? 'number' : kind === 'date' ? 'date' : key === 'email' ? 'email' : 'text'} min={kind === 'number' ? 0 : undefined} value={kind === 'date' ? stringValue.slice(0, 10) : stringValue} onChange={event => onChange(kind === 'number' ? Number(event.target.value) : event.target.value)} />}</label>;
}

function ContentEditor({ module, record, onClose, onSaved, isNew = false }: { module: AdminModule; record: ContentRecord; onClose: () => void; onSaved: () => void; isNew?: boolean }) {
  const { data, save } = useCms(); const { t, lang } = useLanguage();
  const [draft, setDraft] = useState<ContentRecord>(() => ({ ...record }));
  const [tab, setTab] = useState('content'), [busy, setBusy] = useState(false), [error, setError] = useState('');
  const [mediaOpen, setMediaOpen] = useState(false);
  const isFAQ = module.key === 'faqs', isMedia = module.key === 'media';
  const noBody = ['blog_categories', 'features', 'album_images', 'navigation_items', 'social_links', 'team_members', 'testimonials', 'media', 'hero_slides', 'faqs'].includes(module.key);
  function update(key: string, value: unknown) { setDraft(previous => ({ ...previous, [key]: value, ...(key === 'title_en' && isNew && (!previous.slug || previous.slug === slugify(previous.title_en)) ? { slug: slugify(String(value)) } : {}) })); }
  const specificFields = [...(extraFields[module.key] || []), ...(module.key === 'pages' ? pageFields(draft.slug) : [])];
  if (module.key === 'album_images') specificFields.unshift({ key: 'album_id', en: 'Gallery album', ar: 'ألبوم المعرض', kind: 'select', required: true, options: (data.albums || []).map(item => ({ value: item.id, label: contentTitle(item, lang) })) });
  if (module.key === 'blog_posts') specificFields.unshift({ key: 'category_id', en: 'Category', ar: 'التصنيف', kind: 'select', options: (data.blog_categories || []).map(item => ({ value: item.id, label: contentTitle(item, lang) })) });
  const managedFields = new Set([...BASE_COLUMNS, ...specificFields.map(item => item.key), 'meta_title_en', 'meta_title_ar', 'meta_description_en', 'meta_description_ar', 'og_image', 'alt_text_en', 'alt_text_ar', 'demo', 'storage_path', 'mime_type', 'size', ...(['faqs', 'services'].includes(module.key) ? ['category'] : []), ...(module.key === 'blog_posts' ? ['category', 'category_en', 'category_ar', 'author', 'tags'] : []), ...(module.key === 'navigation_items' ? ['url'] : [])]);
  const fieldWords: Record<string, string> = { title: 'العنوان', description: 'الوصف', image: 'الصورة', stats: 'الإحصائيات', value: 'القيمة', label: 'الوصف', cta: 'زر الإجراء', content: 'المحتوى', text: 'النص', link: 'الرابط', background: 'الخلفية' };
  Object.keys(record).filter(key => !managedFields.has(key) && !['boolean', 'undefined'].includes(typeof record[key]) && record[key] !== null).forEach(key => {
    const value = record[key];
    const language = key.endsWith('_ar') ? 'Arabic' : key.endsWith('_en') ? 'English' : '';
    const base = key.replace(/_(en|ar)$/, '');
    const label = base.replaceAll('_', ' ').replace(/^./, letter => letter.toUpperCase());
    const arabic = base.split('_').map(word => fieldWords[word] || word).join(' ');
    specificFields.push({ key, en: `${label}${language ? ` · ${language}` : ''}`, ar: `${arabic}${language ? ` · ${language === 'Arabic' ? 'العربية' : 'الإنجليزية'}` : ''}`, kind: Array.isArray(value) && value.every(item => typeof item === 'string') ? 'lines' : typeof value === 'object' ? 'json' : typeof value === 'number' ? 'number' : String(value).length > 120 ? 'textarea' : 'text', wide: typeof value === 'object' && !Array.isArray(value) });
  });
  async function submit(event: FormEvent) {
    event.preventDefault(); setError('');
    if (!draft.title_en.trim() || !draft.title_ar.trim()) { setTab('content'); setError(t('Please add a title in both English and Arabic.', 'يرجى إضافة عنوان باللغتين الإنجليزية والعربية.')); return; }
    if (!isMedia && !draft.slug.trim()) { setTab('publishing'); setError(t('Please add a URL slug.', 'يرجى إضافة اسم للرابط.')); return; }
    if (draft.slug && (data[module.key] || []).some(item => item.slug === draft.slug && item.id !== draft.id)) { setTab('publishing'); setError(t('This URL slug is already in use. Choose a unique slug.', 'اسم الرابط مستخدم بالفعل. اختر اسماً فريداً.')); return; }
    if (specificFields.some(item => item.required && !field(draft, item.key).trim())) { setTab('details'); setError(t('Please complete all required detail fields.', 'يرجى إكمال جميع حقول التفاصيل المطلوبة.')); return; }
    if (draft.image && !safeImageUrl(draft.image)) { setTab('media'); setError(t('Use a valid image URL or choose an image from the library.', 'استخدم رابط صورة صحيحاً أو اختر صورة من المكتبة.')); return; }
    for (const key of ['cta_link', 'secondary_link', 'href', 'url']) if (field(draft, key) && !safeUrl(field(draft, key))) { setTab('details'); setError(t('Links must be valid website paths or http(s), mailto, or tel URLs.', 'يجب أن تكون الروابط مسارات صحيحة أو روابط http(s) أو mailto أو tel.')); return; }
    if (module.key === 'testimonials' && draft.rating && (Number(draft.rating) < 1 || Number(draft.rating) > 5)) { setTab('details'); setError(t('Rating must be between 1 and 5.', 'يجب أن يكون التقييم بين ١ و٥.')); return; }
    setBusy(true);
    try {
      const next = { ...draft };
      specificFields.filter(item => item.kind === 'lines').forEach(item => { if (Array.isArray(next[item.key])) next[item.key] = (next[item.key] as string[]).map(value => value.trim()).filter(Boolean); });
      specificFields.filter(item => item.kind === 'json').forEach(item => {
        if (typeof next[item.key] === 'string') { try { next[item.key] = JSON.parse(String(next[item.key])); } catch { throw new Error(t('Invalid structured content. Use valid JSON.', 'المحتوى المنظّم غير صالح. استخدم JSON صحيحاً.')); } }
      });
      if (module.key === 'blog_posts') { const category = (data.blog_categories || []).find(item => item.id === next.category_id); next.category = category?.title_en || ''; next.category_en = category?.title_en || ''; next.category_ar = category?.title_ar || ''; next.author = next.author_en; next.tags = next.tags_en; }
      if (module.key === 'navigation_items') next.url = next.href;
      if (module.key === 'faqs' || module.key === 'services') next.category = next.category_en;
      if (module.key === 'testimonials') { next.content_en = next.description_en; next.content_ar = next.description_ar; }
      if (module.key === 'media' && !next.slug) next.slug = 'media-' + next.id;
      await save(module.key, next); onSaved();
    } catch (err) { setError(errorText(err)); } finally { setBusy(false); }
  }
  const tabs = [{ key: 'content', en: 'Content', ar: 'المحتوى' }, ...(specificFields.length ? [{ key: 'details', en: 'Details', ar: 'التفاصيل' }] : []), { key: 'media', en: 'Media', ar: 'الوسائط' }, { key: 'seo', en: 'SEO', ar: 'البحث' }, { key: 'publishing', en: 'Publishing', ar: 'النشر' }];
  return <Modal title={isNew ? t(`Create · ${module.en}`, `إنشاء · ${module.ar}`) : t('Edit content', 'تعديل المحتوى')} onClose={() => { if (!busy) onClose(); }}><form onSubmit={submit} noValidate><div className="admin-editor-tabs" role="tablist">{tabs.map(item => <button key={item.key} role="tab" type="button" aria-selected={tab === item.key} aria-controls={`admin-editor-panel-${item.key}`} id={`admin-editor-tab-${item.key}`} className={tab === item.key ? 'active' : ''} onClick={() => setTab(item.key)}>{t(item.en, item.ar)}</button>)}</div><div className="admin-modal-body admin-editor-body">{error && <Alert>{error}</Alert>}<div id={`admin-editor-panel-${tab}`} role="tabpanel" aria-labelledby={`admin-editor-tab-${tab}`}><div className="admin-form-grid">{tab === 'content' && <><div className="admin-field-wide admin-form-intro"><Globe2 size={18} /><p>{t('Create a complete experience in both languages.', 'قدّم تجربة متكاملة بكلتا اللغتين.')}</p></div>{(['en', 'ar'] as const).map(language => <DynamicField key={`title_${language}`} definition={{ key: `title_${language}`, en: `${isFAQ ? 'Question' : isMedia ? 'Image title' : 'Title'} · ${language === 'en' ? 'English' : 'Arabic'}`, ar: `${isFAQ ? 'السؤال' : isMedia ? 'عنوان الصورة' : 'العنوان'} · ${language === 'en' ? 'الإنجليزية' : 'العربية'}`, required: true }} value={draft[`title_${language}`]} onChange={value => update(`title_${language}`, value)} />)}{!isMedia && (['en', 'ar'] as const).map(language => <DynamicField key={`description_${language}`} definition={{ key: `description_${language}`, en: `${isFAQ ? 'Answer' : module.key === 'testimonials' ? 'Customer quote' : 'Short description'} · ${language === 'en' ? 'English' : 'Arabic'}`, ar: `${isFAQ ? 'الإجابة' : module.key === 'testimonials' ? 'رأي العميل' : 'الوصف المختصر'} · ${language === 'en' ? 'الإنجليزية' : 'العربية'}`, kind: 'textarea' }} value={draft[`description_${language}`]} onChange={value => update(`description_${language}`, value)} />)}{!noBody && (['en', 'ar'] as const).map(language => <DynamicField key={`content_${language}`} definition={{ key: `content_${language}`, en: `Full content · ${language === 'en' ? 'English' : 'Arabic'}`, ar: `المحتوى الكامل · ${language === 'en' ? 'الإنجليزية' : 'العربية'}`, kind: 'textarea', wide: true }} value={draft[`content_${language}`]} onChange={value => update(`content_${language}`, value)} />)}</>}{tab === 'details' && specificFields.map(definition => <DynamicField key={definition.key} definition={definition} value={draft[definition.key]} onChange={value => update(definition.key, value)} />)}{tab === 'media' && <><div className="admin-field-wide admin-editor-image">{draft.image ? <img src={safeImageUrl(draft.image)} alt={localized(draft, 'alt_text', lang) || contentTitle(draft, lang)} /> : <span><Image size={36} />{t('Select a striking image for this content.', 'اختر صورة مميزة لهذا المحتوى.')}</span>}</div><DynamicField definition={{ key: 'image', en: 'Image URL', ar: 'رابط الصورة', wide: true }} value={draft.image} onChange={value => update('image', value)} /><button type="button" className="admin-button admin-field-wide" onClick={() => setMediaOpen(value => !value)}><Images size={17} />{t('Choose from media library', 'الاختيار من مكتبة الوسائط')}</button>{mediaOpen && <div className="admin-media-picker admin-field-wide">{(data.media || []).length ? (data.media || []).map(item => <button type="button" key={item.id} onClick={() => { update('image', item.image || field(item, 'url')); update('alt_text_en', field(item, 'alt_text_en')); update('alt_text_ar', field(item, 'alt_text_ar')); setMediaOpen(false); }} aria-label={contentTitle(item, lang)}><img src={safeImageUrl(item.image || field(item, 'url'))} alt={contentTitle(item, lang)} /><span>{contentTitle(item, lang)}</span></button>) : <p>{t('Upload images in the Media library first, or paste an image URL above.', 'ارفع الصور في مكتبة الوسائط أولاً، أو الصق رابط الصورة أعلاه.')}</p>}</div>}{(['en', 'ar'] as const).map(language => <DynamicField key={`alt_text_${language}`} definition={{ key: `alt_text_${language}`, en: `Image alt text · ${language === 'en' ? 'English' : 'Arabic'}`, ar: `النص البديل للصورة · ${language === 'en' ? 'الإنجليزية' : 'العربية'}` }} value={draft[`alt_text_${language}`]} onChange={value => update(`alt_text_${language}`, value)} />)}</>}{tab === 'seo' && <><p className="admin-help admin-field-wide">{t('Help people discover Apex Motors. Keep titles concise and descriptions specific to this content.', 'ساعد الجمهور في اكتشاف أبيكس موتورز. اجعل العناوين موجزة والأوصاف متعلقة بهذا المحتوى.')}</p>{(['en', 'ar'] as const).flatMap(language => [{ key: `meta_title_${language}`, en: `SEO title · ${language === 'en' ? 'English' : 'Arabic'}`, ar: `عنوان البحث · ${language === 'en' ? 'الإنجليزية' : 'العربية'}` }, { key: `meta_description_${language}`, en: `Meta description · ${language === 'en' ? 'English' : 'Arabic'}`, ar: `وصف البحث · ${language === 'en' ? 'الإنجليزية' : 'العربية'}`, kind: 'textarea' as const }]).map(definition => <DynamicField key={definition.key} definition={definition} value={draft[definition.key]} onChange={value => update(definition.key, value)} />)}<DynamicField definition={{ key: 'og_image', en: 'Social sharing image URL', ar: 'رابط صورة المشاركة الاجتماعية', wide: true }} value={draft.og_image} onChange={value => update('og_image', value)} /></>}{tab === 'publishing' && <><DynamicField definition={{ key: 'slug', en: 'URL slug', ar: 'اسم الرابط', required: true, wide: true }} value={draft.slug} onChange={value => update('slug', slugify(String(value)))} /><DynamicField definition={{ key: 'status', en: 'Publication status', ar: 'حالة النشر', kind: 'select', options: [{ value: 'draft', label: t('Draft', 'مسودة') }, { value: 'published', label: t('Published', 'منشور') }, { value: 'archived', label: t('Archived', 'مؤرشف') }] }} value={draft.status} onChange={value => update('status', value)} /><DynamicField definition={{ key: 'sort_order', en: 'Display order', ar: 'ترتيب العرض', kind: 'number' }} value={draft.sort_order} onChange={value => update('sort_order', value)} /><label className="admin-checkbox admin-field-wide"><input type="checkbox" checked={draft.active} onChange={event => update('active', event.target.checked)} /><span><strong>{t('Active on the website', 'نشط على الموقع')}</strong><small>{t('Content must be published and active to appear publicly.', 'يجب نشر المحتوى وتفعيله ليظهر للزوار.')}</small></span></label><p className="admin-help admin-field-wide">{t('Created', 'أُنشئ')}: {dateLabel(record.created_at, lang)} · {t('Last updated', 'آخر تحديث')}: {dateLabel(record.updated_at, lang)}</p></>}</div></div></div><div className="admin-editor-footer"><Badge status={draft.status} /><div><button type="button" className="admin-button" disabled={busy} onClick={onClose}>{t('Cancel', 'إلغاء')}</button><button type="submit" className="admin-button admin-button-primary" disabled={busy}>{busy ? <Loader2 className="admin-spin" size={16} /> : <Save size={16} />}{t('Save changes', 'حفظ التغييرات')}</button></div></div></form></Modal>;
}

function UploadModal({ onClose, onSuccess }: { onClose: () => void; onSuccess: () => void }) {
  const { uploadMedia } = useCms(); const { t } = useLanguage();
  const [file, setFile] = useState<File | null>(null), [preview, setPreview] = useState(''), [title, setTitle] = useState(''), [titleAr, setTitleAr] = useState(''), [alt, setAlt] = useState(''), [altAr, setAltAr] = useState(''), [error, setError] = useState(''), [busy, setBusy] = useState(false);
  useEffect(() => { if (!file) { setPreview(''); return; } const url = URL.createObjectURL(file); setPreview(url); return () => URL.revokeObjectURL(url); }, [file]);
  async function submit(event: FormEvent) { event.preventDefault(); if (!file) { setError(t('Choose an image to upload.', 'اختر صورة لرفعها.')); return; } if (!['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/avif'].includes(file.type) || file.size > 5 * 1024 * 1024) { setError(t('Choose a JPG, PNG, WebP, GIF, or AVIF image up to 5 MB.', 'اختر صورة JPG أو PNG أو WebP أو GIF أو AVIF بحجم أقصاه ٥ ميغابايت.')); return; } setBusy(true); setError(''); try { await uploadMedia(file, { title_en: title || file.name, title_ar: titleAr, alt_text_en: alt, alt_text_ar: altAr, status: 'published', active: true }); onSuccess(); } catch (err) { setError(errorText(err)); } finally { setBusy(false); } }
  return <Modal title={t('Upload media', 'رفع وسائط')} onClose={() => { if (!busy) onClose(); }}><form onSubmit={submit}><div className="admin-modal-body">{error && <Alert>{error}</Alert>}<label className="admin-upload-zone">{preview ? <img src={preview} alt={t('Upload preview', 'معاينة الصورة')} /> : <UploadCloud size={36} />}<strong>{file ? file.name : t('Choose an image', 'اختر صورة')}</strong><span>{t('JPG, PNG, WebP, GIF or AVIF · Up to 5 MB', 'JPG أو PNG أو WebP أو GIF أو AVIF · حتى ٥ ميغابايت')}</span><input type="file" accept="image/jpeg,image/png,image/webp,image/gif,image/avif" onChange={event => { setFile(event.target.files?.[0] || null); setError(''); }} required /></label><div className="admin-form-grid"><DynamicField definition={{ key: 'upload_title_en', en: 'Image title · English', ar: 'عنوان الصورة · الإنجليزية', required: true }} value={title} onChange={value => setTitle(String(value))} /><DynamicField definition={{ key: 'upload_title_ar', en: 'Image title · Arabic', ar: 'عنوان الصورة · العربية', required: true }} value={titleAr} onChange={value => setTitleAr(String(value))} /><DynamicField definition={{ key: 'upload_alt_en', en: 'Alt text · English', ar: 'النص البديل · الإنجليزية', required: true }} value={alt} onChange={value => setAlt(String(value))} /><DynamicField definition={{ key: 'upload_alt_ar', en: 'Alt text · Arabic', ar: 'النص البديل · العربية', required: true }} value={altAr} onChange={value => setAltAr(String(value))} /></div></div><div className="admin-editor-footer"><span className="admin-help">{t('Describe the image for screen readers.', 'صِف الصورة لمستخدمي قارئ الشاشة.')}</span><div><button type="button" className="admin-button" disabled={busy} onClick={onClose}>{t('Cancel', 'إلغاء')}</button><button className="admin-button admin-button-primary" disabled={busy}>{busy ? <Loader2 className="admin-spin" size={16} /> : <UploadCloud size={16} />}{t('Upload image', 'رفع الصورة')}</button></div></div></form></Modal>;
}

function MessageViewer({ record, onClose }: { record: ContentRecord; onClose: () => void }) {
  const { save } = useCms(); const { t, lang } = useLanguage(); const [busy, setBusy] = useState(false), [error, setError] = useState('');
  async function toggle() { setBusy(true); try { await save('contact_messages', { ...record, is_read: !record.is_read }); } catch (err) { setError(errorText(err)); } finally { setBusy(false); } }
  return <Modal title={t('Customer message', 'رسالة العميل')} onClose={onClose}><div className="admin-modal-body">{error && <Alert>{error}</Alert>}<div className="admin-message-heading"><span className="admin-initials">{field(record, 'name').slice(0, 2).toUpperCase()}</span><div><h3>{field(record, 'name')}</h3><a href={`mailto:${field(record, 'email')}`}>{field(record, 'email')}</a></div><Badge status={record.is_read ? 'read' : 'unread'} /></div><div className="admin-message-meta"><span>{dateLabel(record.created_at, lang)}</span>{field(record, 'phone') && <a href={`tel:${field(record, 'phone')}`}>{field(record, 'phone')}</a>}</div><h3>{field(record, 'subject')}</h3><p className="admin-message-body">{field(record, 'message')}</p><div className="admin-modal-actions"><button className="admin-button" disabled={busy} onClick={() => void toggle()}><Check size={16} />{record.is_read ? t('Mark unread', 'تحديد كغير مقروءة') : t('Mark read', 'تحديد كمقروءة')}</button><a className="admin-button admin-button-primary" href={`mailto:${encodeURIComponent(field(record, 'email'))}?subject=${encodeURIComponent(`Re: ${field(record, 'subject')}`)}`}><Mail size={16} />{t('Reply by email', 'الرد بالبريد')}</a></div></div></Modal>;
}

function SubscriberEditor({ record, onClose }: { record: ContentRecord; onClose: () => void }) {
  const { save } = useCms(); const { t, lang } = useLanguage(); const [status, setStatus] = useState(record.status), [busy, setBusy] = useState(false), [error, setError] = useState('');
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); try { await save('newsletter_subscribers', { ...record, status, active: status === 'active' }); onClose(); } catch (err) { setError(errorText(err)); } finally { setBusy(false); } }
  return <Modal title={t('Subscriber details', 'تفاصيل المشترك')} onClose={onClose} narrow><form onSubmit={submit}><div className="admin-modal-body">{error && <Alert>{error}</Alert>}<h3>{field(record, 'name') || field(record, 'email')}</h3><p dir="ltr">{field(record, 'email')}</p><p className="admin-help">{t('Subscribed', 'تاريخ الاشتراك')}: {dateLabel(record.created_at, lang)}</p><DynamicField definition={{ key: 'subscriber_status', en: 'Subscription status', ar: 'حالة الاشتراك', kind: 'select', options: [{ value: 'active', label: t('Active', 'نشط') }, { value: 'inactive', label: t('Inactive', 'غير نشط') }] }} value={status} onChange={value => setStatus(String(value))} /><div className="admin-modal-actions"><button className="admin-button" type="button" onClick={onClose}>{t('Cancel', 'إلغاء')}</button><button className="admin-button admin-button-primary" disabled={busy}>{busy && <Loader2 className="admin-spin" size={16} />}{t('Save changes', 'حفظ التغييرات')}</button></div></div></form></Modal>;
}

function SiteSettings() {
  const { section = 'website' } = useParams(); const { data, save } = useCms(); const { t } = useLanguage();
  const current = (data.site_settings || []).find(item => item.slug === 'general') || (data.site_settings || [])[0];
  const [draft, setDraft] = useState<ContentRecord>(() => current || emptyRecord({ slug: 'general', title_en: 'Website settings', title_ar: 'إعدادات الموقع', status: 'published' }));
  const [busy, setBusy] = useState(false), [error, setError] = useState(''), [notice, setNotice] = useState('');
  useEffect(() => { if (current) setDraft(current); setNotice(''); setError(''); }, [current, section]);
  const definition = settingsFields[section];
  if (!definition) return <Navigate to="/admin/settings/website" replace />;
  const names: Record<string, [string, string]> = { website: ['Website settings', 'إعدادات الموقع'], footer: ['Footer settings', 'إعدادات التذييل'], seo: ['SEO settings', 'إعدادات البحث'] };
  async function submit(event: FormEvent) { event.preventDefault(); setError(''); setNotice(''); for (const key of ['site_url', 'logo', 'favicon', 'og_image']) if (field(draft, key) && !(key === 'site_url' ? safeUrl(field(draft, key)) : safeImageUrl(field(draft, key)))) { setError(t('Please enter valid website and image URLs.', 'يرجى إدخال روابط صحيحة للموقع والصور.')); return; } setBusy(true); try { await save('site_settings', { ...draft, slug: 'general', status: 'published', active: true }); setNotice(t('Your website settings have been saved.', 'تم حفظ إعدادات موقعك.')); } catch (err) { setError(errorText(err)); } finally { setBusy(false); } }
  return <><div className="admin-page-heading"><div><span className="admin-eyebrow">{t('MAKE IT YOURS', 'اجعله يعكس هويتك')}</span><h1>{t(...names[section])}</h1><p>{t('The details that make your website distinctly Apex Motors.', 'التفاصيل التي تمنح موقعك هوية أبيكس موتورز المميزة.')}</p></div></div><form className="admin-panel admin-settings-panel" onSubmit={submit}><div className="admin-settings-tabs"><NavLink to="/admin/settings/website">{t('Company & contact', 'الشركة والتواصل')}</NavLink><NavLink to="/admin/settings/footer">{t('Footer', 'التذييل')}</NavLink><NavLink to="/admin/settings/seo">{t('Search & sharing', 'البحث والمشاركة')}</NavLink></div><div className="admin-settings-body">{error && <Alert>{error}</Alert>}{notice && <Alert success>{notice}</Alert>}<div className="admin-form-grid">{definition.map(item => <DynamicField key={item.key} definition={item} value={draft[item.key]} onChange={value => setDraft(previous => ({ ...previous, [item.key]: value }))} />)}</div>{section === 'footer' && <div className="admin-settings-links"><Link to={modulePath('navigation_items')}>{t('Manage footer links', 'إدارة روابط التذييل')}<ArrowUpRight size={15} /></Link><Link to={modulePath('social_links')}>{t('Manage social profiles', 'إدارة حسابات التواصل')}<ArrowUpRight size={15} /></Link></div>}</div><div className="admin-editor-footer"><p className="admin-help">{t('Saved settings are reflected across the public website.', 'تنعكس الإعدادات المحفوظة على جميع صفحات الموقع.')}</p><button className="admin-button admin-button-primary" disabled={busy}>{busy ? <Loader2 className="admin-spin" size={16} /> : <Save size={16} />}{t('Save settings', 'حفظ الإعدادات')}</button></div></form></>;
}

function Administrators() {
  const { user, isDemo } = useAuth(); const { t } = useLanguage();
  return <><div className="admin-page-heading"><div><span className="admin-eyebrow">{t('ACCESS & SECURITY', 'الوصول والأمان')}</span><h1>{t('Administrators', 'المسؤولون')}</h1><p>{t('Keep access to your website in trusted hands.', 'اجعل إدارة الوصول إلى موقعك بين أيدٍ موثوقة.')}</p></div></div><section className="admin-panel admin-access-panel"><span className="admin-access-icon"><ShieldCheck size={32} /></span><h2>{t('Your current session', 'جلستك الحالية')}</h2><p dir="ltr">{user?.email}</p><Badge status="active" /><hr /><h3>{t('Manage authorized administrators', 'إدارة المسؤولين المخوّلين')}</h3><p>{isDemo ? t('This is a local demonstration account. Connect Supabase to use verified administrator accounts and a shared database.', 'هذا حساب عرض محلي. اربط Supabase لاستخدام حسابات مسؤولين موثّقة وقاعدة بيانات مشتركة.') : t('Administrator identities are managed in Supabase Authentication. A project owner must create or invite a user, then assign the admin role in the profiles table using the secure SQL workflow in the project README.', 'تُدار هويات المسؤولين في Supabase Authentication. يجب على مالك المشروع إنشاء المستخدم أو دعوته، ثم إسناد دور admin في جدول profiles باستخدام إجراء SQL الآمن الموضح في README.')}</p><p className="admin-help">{t('Administrator roles cannot be granted from the public website. This prevents account privilege escalation.', 'لا يمكن منح صلاحيات المسؤول من الموقع العام، لحماية الحسابات من رفع الصلاحيات غير المصرّح به.')}</p><a href="https://supabase.com/dashboard" target="_blank" rel="noopener noreferrer" className="admin-button">{t('Open Supabase dashboard', 'فتح لوحة تحكم Supabase')}<ExternalLink size={15} /></a></section></>;
}

export default function AdminApp() {
  const { isAdmin, loading } = useAuth(); const location = useLocation();
  useEffect(() => { document.title = 'Apex Motors · Content Studio'; }, [location.pathname]);
  if (location.pathname === '/admin/login') return <Login />;
  if (loading) return <div className="admin-root"><Loading /></div>;
  if (!isAdmin) return <Navigate to="/admin/login" replace />;
  return <Shell />;
}
